/* Thêm bài mới: thêm một object vào mảng LESSONS.
   q1: chọn 1 đáp án -> a là chỉ số đáp án đúng.
   q2: chọn 1 hoặc nhiều đáp án -> a là mảng chỉ số đáp án đúng. */
const LESSONS = [
{ id: "06", title: "Phân quyền truy cập", topics: [
{ t: "Khái niệm, AAA và ma trận điều khiển truy cập",
  s: `<p><b>Điều khiển truy cập</b> cho phép <b>chủ thể</b> (người dùng, tiến trình, thiết bị) truy cập tài nguyên ở một mức quyền xác định. Mô hình <b>AAA</b> gồm Authentication (xác thực chủ thể), Authorization (phân quyền) và Auditing (kiểm toán). <b>Reference Monitor</b> kiểm tra mọi yêu cầu theo chính sách; nó phải không thể vòng tránh, chống sửa đổi và có thể thẩm tra.</p>
<p><b>Ma trận điều khiển truy cập</b>: A(s<sub>i</sub>, o<sub>j</sub>) là tập quyền của chủ thể s<sub>i</sub> trên tài nguyên o<sub>j</sub>. Ma trận quá lớn nên được cài đặt gián tiếp: tách theo cột là <b>ACL</b> (mỗi tài nguyên có danh sách chủ thể và quyền, cần xác thực danh tính); tách theo dòng là <b>Capability List</b> (mỗi chủ thể giữ thẻ quyền, có thể chuyển cho người khác, không cần xác thực, nhưng phải chống giả mạo và replay).</p>`,
  q1: { q: "Thành phần nào của mô hình AAA xác định đúng chủ thể thực hiện hành vi truy nhập?",
    o: ["Authentication", "Authorization", "Auditing", "Reference Monitor"], a: 0,
    e: "Authentication (xác thực) xác định đúng chủ thể; Authorization là phân quyền; Auditing là giám sát hành vi truy cập." },
  q2: { q: "Chọn các phát biểu đúng về ACL và Capability List.",
    o: ["ACL phân rã ma trận theo cột, hướng tài nguyên", "Capability List phân rã ma trận theo dòng, hướng chủ thể", "ACL không cần xác thực danh tính chủ thể", "Capability có thể được truyền từ chủ thể này sang chủ thể khác"], a: [0, 1, 3],
    e: "ACL cần xác thực danh tính để chống giả mạo. Capability dạng thẻ truy cập có thể chuyển giao và không cần xác thực chủ thể." } },

{ t: "DAC: điều khiển truy cập tùy nghi",
  s: `<p><b>DAC</b> (Discretionary Access Control): quyền của mỗi cặp (chủ thể, tài nguyên) do <b>chủ sở hữu</b> tài nguyên quyết định. Mô hình này phổ biến trong hệ điều hành nhưng quản trị lỏng lẻo, không kiểm soát được sự lan truyền quyền và dòng thông tin. Ví dụ: Bob không được đọc tệp A, nhưng nhờ (hoặc đánh lừa) Alice đọc A rồi chép sang tệp B mà Bob được đọc.</p>
<p>Trong SQL: <code>GRANT quyền ON đối_tượng TO người_dùng [WITH GRANT OPTION]</code> để cấp quyền và <code>REVOKE</code> để thu hồi. Với <code>WITH GRANT OPTION</code>, B có thể cấp tiếp cho C mà chủ sở hữu không biết. Khi A thu hồi quyền của B, mọi quyền B đã lan truyền đi cũng bị thu hồi.</p>`,
  q1: { q: "A cấp quyền R trên bảng O cho B với WITH GRANT OPTION; B cấp R cho C. Sau đó A thu hồi R từ B. Điều gì xảy ra với C?",
    o: ["C vẫn giữ quyền R", "C cũng bị thu hồi quyền R", "Lệnh REVOKE báo lỗi", "Chỉ bị thu hồi nếu B đồng ý"], a: 1,
    e: "Các quyền phát sinh do lan truyền từ B đều bị thu hồi theo khi A thu hồi quyền của B." },
  q2: { q: "Chọn các hạn chế của DAC.",
    o: ["Không quản lý được sự lan truyền của quyền", "Cho phép thông tin truyền giữa các chủ thể mà không có chính sách kiểm soát", "Quyền được cấp theo chính sách chung của hệ thống", "Chủ sở hữu có thể không biết quyền đã lan truyền qua GRANT OPTION"], a: [0, 1, 3],
    e: "Cấp quyền theo chính sách chung của hệ thống là đặc điểm của MAC, không phải DAC." } },

{ t: "MAC: Bell-LaPadula, Biba và Chinese Wall",
  s: `<p><b>MAC</b> (Mandatory Access Control): quyền được cấp theo chính sách chung dựa trên phân loại chủ thể (độ tin cậy) và tài nguyên (độ nhạy cảm). Ưu điểm: quản trị tập trung, bảo mật cao. Nhược điểm: phải phân loại rõ ràng, phạm vi ứng dụng hẹp.</p>
<p><b>Bell-LaPadula</b> bảo vệ <i>tính bí mật</i>: TS &gt; S &gt; C &gt; UC. Simple Security: <i>no-read-up</i> (chỉ đọc khi mức chủ thể ≥ mức đối tượng). *-Property: <i>no-write-down</i> (chỉ ghi khi mức chủ thể ≤ mức đối tượng).</p>
<p><b>Biba</b> bảo vệ <i>tính toàn vẹn</i>: Crucial &gt; Very Important &gt; Important. <i>No-write-up</i>: chỉ ghi khi mức chủ thể ≥ mức đối tượng. <i>No-read-down</i>: chỉ đọc khi mức chủ thể ≤ mức đối tượng. <b>Chinese Wall</b>: tài nguyên chia thành các nhóm tranh chấp; đã truy cập đối tượng O thì mất quyền truy cập mọi O′ ≠ O trong cùng nhóm.</p>`,
  q1: { q: "Theo Bell-LaPadula, Sally (Secret) có quyền gì với Activity Log Files (Confidential)?",
    o: ["Chỉ đọc", "Chỉ ghi", "Đọc và ghi", "Không đọc, không ghi"], a: 0,
    e: "Secret ≥ Confidential nên được đọc (no-read-up). Ghi xuống mức thấp hơn bị cấm (no-write-down)." },
  q2: { q: "Theo Biba, Bob (Very Important) với File A (Crucial) và File C (Important): chọn các phát biểu đúng.",
    o: ["Bob có thể ghi File C", "Bob có thể ghi File A", "Bob có thể đọc File A", "Bob có thể đọc File C"], a: [0, 2],
    e: "Ghi được khi mức chủ thể ≥ đối tượng (File C). Đọc được khi mức chủ thể ≤ đối tượng (File A)." } },

{ t: "RBAC: điều khiển truy cập theo vai trò",
  s: `<p><b>RBAC</b> (Role-based Access Control) gán quyền cho <b>vai trò</b> (nhóm nhiệm vụ trong tổ chức) thay vì cho từng người dùng cuối. Mỗi vai trò có quyền lâu dài; mỗi người dùng được gán một hoặc nhiều vai trò.</p>
<p><b>RBAC<sub>0</sub></b>: UA ⊆ U × R (gán vai trò cho người dùng), PA ⊆ P × R (gán quyền cho vai trò), và tập phiên S, trong đó người dùng dùng một hoặc nhiều vai trò. <b>RBAC<sub>1</sub></b> thêm <i>phân cấp vai trò</i>: vai trò cấp cao thừa hưởng quyền của vai trò cấp thấp.</p>
<p>Ưu điểm: diễn tả tốt chính sách tổ chức (tách biệt nhiệm vụ, ủy nhiệm), linh hoạt (yêu cầu mới chỉ đổi cách gán quyền vào vai trò) và co dãn tốt.</p>`,
  q1: { q: "Trong RBAC, quyền truy cập được gán trực tiếp cho đối tượng nào?",
    o: ["Người dùng cuối", "Vai trò", "Phiên truy cập", "Tài nguyên"], a: 1,
    e: "Quyền gán cho vai trò (PA ⊆ P × R); người dùng nhận quyền thông qua vai trò được gán (UA ⊆ U × R)." },
  q2: { q: "Chọn các phát biểu đúng về RBAC.",
    o: ["Mỗi người dùng có thể được gán một hoặc nhiều vai trò", "Quyền được gán trực tiếp cho người dùng cuối", "Ở RBAC1, vai trò cấp cao thừa hưởng quyền của vai trò cấp thấp", "Yêu cầu bảo mật mới chủ yếu chỉ làm thay đổi cách gán quyền vào các vai trò"], a: [0, 2, 3],
    e: "Quyền không gán trực tiếp cho người dùng cuối; đó chính là điều giúp RBAC linh hoạt và co dãn tốt." } },

{ t: "Điều khiển truy cập trong Unix và SELinux",
  s: `<p>Unix dùng ACL rút gọn (Owner, Group, Other) với quyền <code>r</code>, <code>w</code>, <code>x</code>. Thông tin lưu trong 10 bit: bit 1 là loại (<code>-</code> tệp, <code>d</code> thư mục), 9 bit sau là ba nhóm rwx. Ví dụ <code>640</code> = <code>110 100 000</code> = <code>rw-r-----</code>. Lệnh: <code>chown user:group file</code>, <code>chmod permission file</code>. Muốn truy cập tệp cần có quyền trên mọi thư mục trong đường dẫn.</p>
<p><b>Sticky bit</b> bật: chỉ chủ tệp, chủ thư mục hoặc root mới đổi tên hay xóa tệp. Mỗi tiến trình có Real, Effective và Saved UID/GID; tệp có <b>setuid = 1</b> thì Effective UID đổi thành UID chủ tệp (ví dụ <code>passwd</code>). Root có UID = 0 và mọi quyền.</p>
<p><b>SELinux</b> là MAC cho Linux với ba chế độ: Enforcing (thực thi, mặc định), Permissive (chỉ cảnh báo và ghi log), Disabled. Hạn chế của Unix: daemon chạy bằng root, biến môi trường LIBPATH bị sửa, thư mục /tmp, và lỗi TOCTTOU (đổi /tmp/X thành symbolic link tới /etc/shadow giữa lúc kiểm tra và lúc mở).</p>`,
  q1: { q: "Quyền dạng số 640 tương ứng chuỗi nào?",
    o: ["rw-r-----", "rwxr-x---", "rw-rw----", "r--rw----"], a: 0,
    e: "6 = 110 = rw-, 4 = 100 = r--, 0 = 000 = ---." },
  q2: { q: "Chọn các phát biểu đúng.",
    o: ["Khi tệp có setuid = 1, Effective UID của tiến trình đổi thành UID chủ tệp", "Khi sticky bit bật, mọi người có quyền thư mục đều xóa được mọi tệp", "SELinux ở chế độ Permissive chỉ cảnh báo và ghi lại hành động", "Tài khoản root (UID = 0) có mọi quyền truy cập trên tất cả tệp"], a: [0, 2, 3],
    e: "Sticky bit bật thì chỉ chủ tệp, chủ thư mục hoặc root mới được đổi tên hay xóa tệp." } }
]},

{ id: "08", title: "Phần mềm độc hại", topics: [
{ t: "Tổng quan mã độc",
  s: `<p><b>Phần mềm độc hại</b> (malware) là chương trình khi thực thi gây tổn hại tài nguyên hệ thống hoặc chiếm một phần hay toàn bộ quyền điều khiển. Phân loại: <b>virus</b> cần hành động kích hoạt của người dùng để lây; <b>worm</b> (sâu) không cần; <b>trojan</b> ẩn trong tệp có vẻ vô hại và không tự lây. Ranh giới giữa các loại không rõ ràng.</p>
<p>Hành vi gây hại: phá hủy dữ liệu/phần cứng, keylogging, spyware (đánh cắp thông tin), ransomware (mã hóa dữ liệu), coinminer (đánh cắp tài nguyên tính toán), backdoor (cửa hậu), rootkit (che giấu hoạt động), botnet (thực hiện tấn công). Có thể chạy ngay hoặc chờ điều kiện (time bomb, logic bomb). Đường lây: email, tin nhắn, thiết bị lưu trữ di động, chương trình giả mạo, phần mềm bẻ khóa, lỗ hổng phần mềm.</p>`,
  q1: { q: "Loại mã độc nào tự lây nhiễm mà không cần người dùng kích hoạt?",
    o: ["Virus", "Worm", "Trojan", "Keylogger"], a: 1,
    e: "Worm (sâu máy tính) tự lây, thường qua khai thác lỗ hổng. Virus cần kích hoạt; trojan không tự lây." },
  q2: { q: "Chọn các cặp (loại mã độc, hành vi) đúng.",
    o: ["Ransomware: mã hóa dữ liệu người dùng", "Coinminer: đánh cắp tài nguyên tính toán", "Rootkit: tạo cửa hậu cho kẻ tấn công xâm nhập", "Spyware: đánh cắp thông tin"], a: [0, 1, 3],
    e: "Tạo cửa hậu là backdoor. Rootkit có nhiệm vụ che giấu hoạt động của mã độc." } },

{ t: "Virus: cấu trúc, cơ chế lây và phát hiện theo đặc trưng",
  s: `<p>Virus thường có 3 đoạn mã: <b>lây nhiễm</b> (tự sao chép sang chương trình khác), <b>kích hoạt</b> (sự kiện hoặc điều kiện xác định khi nào hoạt động chính bắt đầu) và <b>hoạt động</b> (hành vi phá hoại). Virus được mô tả bằng cách thức lây nhiễm và hành vi phá hoại. Mã thực thi cài sẵn (tệp ứng dụng, phân vùng khởi động, tệp đính kèm email) được người dùng kích hoạt; virus có thể tự sửa đổi, giải mã đoạn mã ẩn, tải thêm từ máy chủ phát tán và lây sang hệ thống khác (tiêm nhiễm vào tệp, USB, gửi email).</p><p><b>Tiêm nhiễm</b>: thay lệnh đầu của tệp .exe bằng lệnh JUMP tới mã virus; cuối mã virus có JUMP về lệnh đầu của chương trình gốc. <b>Phát hiện theo đặc trưng</b>: xây CSDL đặc trưng (thường là mã lây nhiễm ở đầu tệp) rồi so sánh byte với mẫu đã biết. Để lẩn tránh, virus làm đặc trưng khó tìm hơn: nối thêm, bao quanh hoặc chèn giữa chương trình gốc.</p>`,
  q1: { q: "Đoạn mã nào của virus xác định khi nào hoạt động chính được kích hoạt?", o: ["Đoạn mã lây nhiễm", "Đoạn mã kích hoạt", "Đoạn mã hoạt động", "Đoạn mã giải mã"], a: 1, e: "Đoạn mã kích hoạt chứa sự kiện hoặc điều kiện; đoạn mã hoạt động thực hiện hành vi phá hoại." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Virus chỉ lây qua email", "Tiêm nhiễm thay lệnh đầu của tệp .exe bằng lệnh JUMP tới mã virus", "Cuối mã virus có lệnh JUMP về lệnh đầu của chương trình gốc", "Phát hiện theo đặc trưng so sánh byte với CSDL các mẫu virus đã biết"], a: [1, 2, 3], e: "Virus còn lây qua tệp ứng dụng, phân vùng khởi động, thiết bị nhớ di động và nhiều đường khác." } },
{ t: "Virus đa hình và siêu đa hình",
  s: `<p><b>Virus đa hình</b> (polymorphic) mã hóa thân virus bằng một khóa; chương trình gồm decryptor, khóa và mã đã mã hóa. Khi lây, nó đổi khóa và mã hóa lại bằng bộ mã hóa (encrypter) nên bản mã mỗi lần một khác, chỉ decryptor gần như cố định. Phát hiện: (1) dùng đặc trưng “hẹp” cho decryptor (ít byte nên dễ phát hiện nhầm, tin tặc nhanh chóng đổi decryptor); (2) thực thi để so sánh đặc trưng trên mã đã giải mã (khó chọn thời điểm so sánh).</p><p><b>Virus siêu đa hình</b> (metamorphic) tự đổi mã nguồn về ngữ nghĩa mức thấp nhưng giữ nguyên chức năng: chèn mã dư thừa, đổi thanh ghi (Win95/Regswap, 1998), đổi trình tự điều kiện, đổi thứ tự lệnh không ràng buộc (Zperm.A dùng jmp và garbage), thay thuật toán (Win32/Evol). Hướng phát hiện chính là dựa trên hành vi.</p>`,
  q1: { q: "Zperm.A thực hiện kỹ thuật biến hình nào?", o: ["Đổi khóa mã hóa thân virus", "Đổi tên tệp nhiễm", "Sắp xếp lại thứ tự lệnh trong mã của chính nó, nối bằng jmp và mã rác", "Thay đổi chức năng phá hoại"], a: 2, e: "Zperm.A trực tiếp sắp xếp lại các lệnh trong mã của nó và nối chúng bằng lệnh jmp." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Virus siêu đa hình thay đổi chức năng mức cao của virus", "Virus đa hình đổi khóa và mã hóa lại thân virus khi lây", "Decryptor của virus đa hình gần như cố định giữa các bản", "Win95/Regswap dùng kỹ thuật đổi thanh ghi"], a: [1, 2, 3], e: "Virus siêu đa hình không đổi ngữ nghĩa ở mức cao hơn: chức năng và tính năng vẫn giữ nguyên." } },
{ t: "Phân tích mã độc: tĩnh, động và quy trình Sandbox",
  s: `<p><b>Phân tích động</b>: chạy mã độc trong Sandbox và quan sát; nhanh, biết ngay cách hoạt động, nhưng cần môi trường an toàn và không thấy hết mọi hành vi. <b>Phân tích tĩnh</b>: dịch ngược mã thực thi; không cần kích hoạt, xác định đầy đủ cơ chế nhưng phức tạp, đòi hỏi nhân lực giỏi và tốn thời gian.</p><p>Sandbox: tạo máy ảo (VirtualBox, Hyper-V), cài HĐH, tắt hoặc hạn chế card mạng, tắt chia sẻ tệp/thư mục, rồi chuyển mã độc vào; môi trường phải cách ly hoàn toàn và được giám sát. Tĩnh: dịch ngược; BinText (xâu ký tự), UPX (gỡ nén, giải mã). Động: nối mạng vật lý có giám sát, không nối mạng tác nghiệp; Process Monitor, Process Explorer; Wireshark, tcpdump, NetResistent, TCPView cho kết nối mạng; RegShot cho tệp, tiến trình và registry mới; OllyDbg, ProcDump cho mã trên RAM.</p>`,
  q1: { q: "Công cụ nào được dùng để xác định thay đổi các giá trị registry của hệ thống khi mã độc chạy?", o: ["BinText", "UPX", "RegShot", "Wireshark"], a: 2, e: "RegShot so sánh trạng thái registry và tệp trước và sau khi kích hoạt mã độc." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Môi trường phân tích phải được cách ly hoàn toàn với môi trường làm việc", "Phân tích tĩnh không cần kích hoạt mã độc", "Phân tích động đủ để xác định mọi hành vi của mã độc", "Wireshark và tcpdump dùng để bắt và phân tích lưu lượng mạng"], a: [0, 1, 3], e: "Phân tích động không xác định được hết tất cả hành vi của mã độc." } },
{ t: "Lẩn tránh phân tích và rootkit",
  s: `<p>Mã độc chống phân tích tĩnh bằng đoạn mã phức tạp che giấu hoạt động thật; chống phân tích động bằng cách phát hiện môi trường thực thi để đổi hành vi hoặc tạo hành động kéo dài thời gian thực thi. Phần mềm anti-virus đáp trả bằng cách bỏ qua mã hoặc hành vi vô nghĩa và gắn cờ đoạn mã không quen thuộc; cuộc đua tiếp diễn và tin tặc thường đi trước.</p><p><b>Rootkit/Stealth virus</b> ẩn mình trước phần mềm phát hiện bằng kỹ thuật <i>hook</i> chặn sự kiện và can thiệp xử lý. <b>User-level</b>: hook hàm thư viện, dễ phát hiện. <b>Kernel-level</b>: hook hàm thực thi lời gọi hệ thống, hàm xử lý ngắt, driver, firmware; khó phát hiện. <b>Virtualization-based</b>: ẩn trong môi trường ảo hóa, gần như không thể phát hiện. Phát hiện: hành vi hook, thay đổi số lượng/tần suất/thứ tự lời gọi hệ thống, kiểm tra toàn vẹn tệp hệ thống, so với hệ thống tham chiếu.</p>`,
  q1: { q: "Loại rootkit nào hook vào hàm thực thi lời gọi hệ thống, hàm xử lý ngắt và driver thiết bị?", o: ["User-level rootkit", "Kernel-level rootkit", "Logic bomb", "Keylogger"], a: 1, e: "Kernel-level rootkit can thiệp ở mức nhân hệ điều hành nên khó phát hiện hơn user-level." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Mã độc chống phân tích động bằng cách phát hiện môi trường thực thi để thay đổi hành vi", "Mã độc chống phân tích tĩnh bằng cách tạo ra các đoạn mã phức tạp", "Virtualization-based rootkit là loại dễ phát hiện nhất", "Kiểm tra toàn vẹn tệp hệ thống giúp phát hiện rootkit"], a: [0, 1, 3], e: "Virtualization-based rootkit ẩn trong môi trường ảo hóa nên gần như không thể phát hiện." } },
{ t: "Sâu máy tính: cơ chế lây lan và các sâu kinh điển",
  s: `<p><b>Sâu</b> không cần hành động kích hoạt của người dùng: khai thác lỗ hổng phần mềm, tìm nạn nhân mới (quét dải IP, chọn IP ngẫu nhiên, dùng danh sách có sẵn, truy vấn máy chủ bên thứ ba), rồi quét lỗ hổng tương tự để lây; có thể kết hợp cách lây của virus. Mô hình lan tương tự virus sinh học, rất nhanh; phụ thuộc kích thước mạng, tỉ lệ nút có lỗ hổng, số nút đã nhiễm, tốc độ quét và tần suất giao tiếp với máy chủ.</p><p><b>Morris</b> (1988): sâu đầu tiên, vốn để đo kích thước Internet nhưng vô tình gây DoS; ~10% máy nhiễm, thiệt hại ~100M$. <b>Code Red</b> (2001): lỗ hổng IIS dù bản vá có trước 1 tháng, ~300.000 máy sau 13 giờ; ngày 1–20 lây, từ ngày 20 DoS website Nhà Trắng. <b>SQL Slammer</b> (2003): lỗ hổng MS SQL Server, 1 gói UDP, gấp đôi mỗi 8,5 giây. <b>Blaster</b> (2003): email, ~25 triệu máy. <b>Sasser</b> (2004): Windows 2000/XP, 128 tiến trình quét, cổng 445. <b>Conficker</b> (2008): botnet lớn nhất thời điểm đó; Việt Nam đứng đầu số máy nhiễm.</p>`,
  q1: { q: "Sâu nào có số máy bị nhiễm tăng gấp đôi sau mỗi 8,5 giây?", o: ["Code Red", "SQL Slammer", "Blaster", "Sasser"], a: 1, e: "SQL Slammer đóng gói trong một gói UDP nhỏ và lây tới 75.000 máy sau 10 phút." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Sâu cần người dùng bấm kích hoạt mới lây được", "Tốc độ lây phụ thuộc kích thước mạng và tỉ lệ nút có lỗ hổng", "Code Red lây nhiễm dù bản vá đã có trước đó 1 tháng", "Morris ban đầu được thiết kế để đo kích thước Internet"], a: [1, 2, 3], e: "Sâu không cần hành động kích hoạt của người dùng." } },
{ t: "Các vụ tấn công điển hình và phòng chống",
  s: `<p><b>Stuxnet</b> (2010): nhắm vào mạng SCADA điều khiển máy ly tâm, 59% máy nhiễm ở Iran; 4 lỗ hổng zero-day; lây qua USB rồi Windows RPC; ẩn mình bằng trình điều khiển thiết bị được chứng thực. Chỉ kích hoạt khi tốc độ quay đạt 807–1210 Hz, tăng dần tới 1410 Hz làm hỏng máy, gửi thông báo giả rằng hệ thống bình thường, rồi giảm về mức thường. <b>NotPetya</b>: lỗ hổng MeDoc, EternalBlue và Mimikatz; mã hóa dữ liệu như ransomware nhưng thực chất là DoS; đánh sập Maersk, FedEx. <b>diskperf.exe</b>: nhiễm Vietnam Airlines, mã hóa dữ liệu và tạo backdoor. <b>WannaCry</b> (05/2017): EternalBlue từ công cụ NSA rò rỉ, 230.000 máy.</p><p>Phòng chống: không mở tệp đính kèm hoặc chạy tệp từ nguồn lạ, firewall chặn cổng không cần thiết, gia cố hệ thống, kiểm soát lưu lượng nội bộ, cập nhật bản vá, quét thiết bị USB, phân quyền, dùng phần mềm bản quyền, cài phần mềm diệt virus, xây dựng chính sách và đào tạo người dùng.</p>`,
  q1: { q: "Biện pháp nào sau đây không phù hợp để phòng chống mã độc?", o: ["Cập nhật các bản vá bảo mật", "Quét virus thiết bị USB khi kết nối", "Dùng công cụ bẻ khóa bản quyền phần mềm", "Phân quyền người dùng"], a: 2, e: "Phần mềm bẻ khóa là đường lây mã độc; nên dùng phần mềm bản quyền." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Stuxnet lây chủ yếu qua email hàng loạt", "Stuxnet khởi đầu qua USB rồi lây trong mạng bằng Windows RPC", "WannaCry khai thác lỗ hổng EternalBlue", "NotPetya trông như ransomware nhưng thực chất là tấn công DoS"], a: [1, 2, 3], e: "Stuxnet khởi nguồn từ USB và dùng 4 lỗ hổng zero-day." } }
]},
{ id: "01", title: "Tổng quan an toàn an ninh thông tin", topics: [
{ t: "AT-ANTT là gì và vì sao quan trọng",
  s: `<p><b>AT-ANTT</b> là bảo vệ tài nguyên của hệ thống thông tin (phần cứng, phần mềm, dữ liệu, người dùng) trước các hành vi gây tổn hại, phần lớn là tấn công cố ý: tấn công vật lý vào phần cứng, hoặc tấn công logic bằng chương trình phá hoại can thiệp vào xử lý và truyền dữ liệu.</p><p>Đây là dạng đúng đắn “chặt” hơn: hệ thống phải đúng ngay cả khi có kẻ tấn công, tức là phát hiện được đầu vào độc hại và nguồn trái phép. Tấn công ảnh hưởng tới thân thể, bí mật thông tin, tài sản, tổ chức, kinh tế và an ninh quốc gia.</p>`,
  q1: { q: "Điểm khác biệt chính giữa AT-ANTT và tính đúng đắn thông thường là gì?", o: ["Chỉ cần xử lý đúng các đầu vào hợp lệ", "Phải đúng cả khi có kẻ tấn công, biết xử lý đầu vào độc hại", "Chỉ liên quan đến phần cứng", "Chỉ liên quan đến mật khẩu"], a: 1, e: "AT-ANTT đòi hỏi tính đúng đắn ngay trong ngữ cảnh có sự hiện diện của kẻ tấn công." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Tấn công logic dùng chương trình phá hoại can thiệp vào xử lý và truyền dữ liệu", "Tấn công vật lý nhắm vào phần cứng", "Tài nguyên hệ thống chỉ gồm phần cứng", "Phần lớn hành vi gây tổn hại là tấn công cố ý"], a: [0, 1, 3], e: "Tài nguyên gồm cả phần cứng, phần mềm, dữ liệu và người dùng." } },
{ t: "Chính sách, mô hình CIA và AAA",
  s: `<p><b>Chính sách AT-ANTT</b> tuyên bố mục tiêu và yêu cầu: chủ thể nào, hành vi phải/được phép/không được phép, trên tài nguyên nào. Mô hình <b>CIA</b>: Confidentiality (chỉ bên được cấp quyền được tiếp cận), Integrity (chỉ bên được cấp quyền được sửa đổi), Availability (sẵn sàng: thời gian đáp ứng chấp nhận được, chịu lỗi, dễ sử dụng).</p><p>Mô hình <b>AAA</b>: Assurance (đảm bảo, quản trị được sự tin cậy), Authenticity (khẳng định danh tính chủ thể), Anonymity (che giấu thông tin cá nhân của chủ thể).</p>`,
  q1: { q: "Anonymity trong mô hình AAA có nghĩa là gì?", o: ["Khẳng định danh tính chủ thể", "Che giấu thông tin cá nhân của chủ thể", "Đảm bảo hệ thống luôn sẵn sàng", "Chống sửa đổi dữ liệu"], a: 1, e: "Authenticity là khẳng định danh tính, còn Anonymity là che giấu thông tin cá nhân." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Chính sách AT-ANTT mô tả chủ thể, hành vi và tài nguyên", "Availability bao gồm khả năng chịu lỗi", "Authenticity là che giấu danh tính của chủ thể", "Confidentiality: tài nguyên chỉ được tiếp cận bởi các bên được cấp quyền"], a: [0, 1, 3], e: "Authenticity là khẳng định được danh tính, không phải che giấu." } },
{ t: "Cơ chế an toàn, mô hình đe dọa, rủi ro và lỗ hổng",
  s: `<p>Cơ chế AT-ANTT gồm <b>ngăn chặn</b> (không để chính sách bị xâm phạm) và <b>phát hiện, ứng phó</b> (với xâm phạm không thể ngăn chặn). Phát hiện có <i>false positive</i> (cảnh báo sai) và <i>false negative</i> (bỏ sót tấn công). Ví dụ cơ chế: mật mã, xác thực, ủy quyền, nhật ký, kiểm toán, sao lưu, dự phòng.</p><p><b>Mô hình đe dọa</b> trả lời: cần bảo vệ gì, ai có thể tấn công, tấn công thế nào. Risk = Threat × Impact. <b>Lỗ hổng</b> là điểm yếu có thể bị khai thác (tra cứu tại cvedetails.com); nên tầm soát định kỳ.</p>`,
  q1: { q: "False negative trong phát hiện tấn công là gì?", o: ["Tỉ lệ cảnh báo sai", "Tỉ lệ bỏ sót tấn công", "Tỉ lệ ngăn chặn thành công", "Tỉ lệ lỗ hổng được vá"], a: 1, e: "False positive là cảnh báo sai; false negative là bỏ sót tấn công." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Cần cơ chế phát hiện vì có dạng xâm phạm không thể ngăn chặn", "Sao lưu và dự phòng là các cơ chế AT-ANTT", "Mô hình đe dọa tồi dẫn đến giải pháp an toàn tồi", "Rủi ro không liên quan đến thiệt hại của sự cố"], a: [0, 1, 2], e: "Rủi ro gắn với khả năng xảy ra sự cố và thiệt hại của chúng." } },
{ t: "Kẻ tấn công: động cơ, giả định và phân loại",
  s: `<p>Kẻ tấn công có thể là tội phạm vì tiền hoặc phá hoại, chính phủ các nước, hoặc người thân quen (nguy hiểm nhất). Động cơ: tiền bạc (ransomware, coinminer), gián điệp, chính trị, đùa cợt.</p><p>Giả định bi quan nhưng cần thiết: kẻ tấn công kiên trì, thu thập dễ dàng thông tin thông thường của hệ thống, thử trên hệ thống tương tự, có thể có sẵn một số quyền, tự động hóa và phối hợp được, có nguồn lực tính toán lớn. Phân loại: thụ động/chủ động; có chủ đích (APT)/không chủ đích; bên trong/bên ngoài.</p>`,
  q1: { q: "Tấn công chủ động khác tấn công thụ động ở điểm nào?", o: ["Chỉ nghe lén dữ liệu", "Can thiệp, làm thay đổi hoạt động của hệ thống", "Luôn nhắm vào mục tiêu xác định", "Chỉ xuất phát từ bên trong"], a: 1, e: "Tấn công thụ động không can thiệp hay làm thay đổi hoạt động của hệ thống." },
  q2: { q: "Chọn các giả định đúng về kẻ tấn công.", o: ["Kiên trì tới khi đạt được mục đích", "Không thể truy cập hệ thống tương tự để tìm hiểu cách hoạt động", "Có thể tự động hóa các hành vi tấn công", "Có thể đã có một số quyền truy cập trên hệ thống mục tiêu"], a: [0, 2, 3], e: "Kẻ tấn công có thể dùng hệ thống tương tự để hiểu cách hệ thống mục tiêu hoạt động." } },
{ t: "Quy trình xây dựng và các nguyên lý thiết kế đầu tiên",
  s: `<p>Quy trình 4 giai đoạn: phân tích yêu cầu (chính sách, tình huống lạm quyền, mô hình nguy cơ), thiết kế (hướng bảo mật), triển khai (duyệt mã nguồn), kiểm thử và bảo trì (kiểm thử xâm nhập, giám sát liên tục). Xử lý nguy cơ: ngăn chặn, giảm thiểu, chấp nhận hoặc chuyển nhượng rủi ro.</p><p>Nguyên lý: AT-ANTT là bài toán kinh tế; KISS (phức tạp là kẻ thù); <b>least privilege</b>; phân chia quyền; <b>separation of responsibility</b> (quyền chỉ thực thi khi nhiều bên cùng yêu cầu); chia sẻ tối thiểu; dễ dùng (nếu khó dùng, người dùng sẽ biến nó thành dễ dùng nhưng kém an toàn).</p>`,
  q1: { q: "Mua bảo hiểm cho tài sản thuộc cách xử lý nguy cơ nào?", o: ["Ngăn chặn", "Giảm thiểu", "Chấp nhận", "Chuyển nhượng rủi ro"], a: 3, e: "Chuyển nhượng rủi ro là đưa một phần thiệt hại sang bên thứ ba, như bảo hiểm." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Least privilege: không cấp quyền nhiều hơn mức đối tượng cần để hoàn thành nhiệm vụ", "Separation of responsibility yêu cầu nhiều bên cùng yêu cầu thì quyền mới được thực thi", "Hệ thống càng phức tạp thì càng an toàn", "KISS: giữ hệ thống đơn giản vì độ phức tạp là kẻ thù của an toàn"], a: [0, 1, 3], e: "Độ phức tạp là kẻ thù của an toàn, nên thiết kế cần đơn giản." } },
{ t: "Các nguyên lý còn lại và TCB",
  s: `<p><b>Fail-safe default</b>: mặc định từ chối, dùng whitelist. <b>Complete mediation</b>: kiểm tra mọi truy cập; TOCTTOU là lỗi tranh đua điều kiện khi kiểm tra và sử dụng cách nhau. <b>Defense in depth</b>: nhiều lớp bảo vệ, tăng chi phí và ảnh hưởng hiệu năng. An toàn nằm ở mắt xích yếu nhất. <b>Open design</b>: không dựa vào che giấu. AT-ANTT là quá trình, cần thiết kế từ đầu.</p><p><b>TCB</b> (Trusted Computing Base): tập phần cứng, phần mềm mà hệ thống dựa vào để đạt mục tiêu an toàn. TCB phải không thể vòng tránh, chống sửa đổi, có thể thẩm tra; nên đơn giản (simple = small). Ví dụ: TPM, Secure Enclave, TEE.</p>`,
  q1: { q: "Lỗ hổng TOCTTOU vi phạm nguyên lý thiết kế nào?", o: ["Least privilege", "Complete mediation", "Open design", "Least common mechanism"], a: 1, e: "Kiểm tra tại thời điểm trước rồi dùng sau cho phép dữ liệu đã thay đổi, nên mọi truy cập chưa được kiểm soát đầy đủ." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Defense in depth tạo nhiều lớp bảo vệ nhưng tăng chi phí và ảnh hưởng hiệu năng", "Security through obscurity là cách thiết kế được khuyến nghị", "TCB cần đơn giản và nhỏ để có thể thẩm tra", "An toàn của hệ thống đặt tại mắt xích yếu nhất"], a: [0, 2, 3], e: "Thiết kế mở: không dựa vào việc che giấu thiết kế." } }
]},
{ id: "02", title: "Mật mã học: mã mật", topics: [
{ t: "Lược sử mật mã và nguyên lý Kerckhoffs",
  s: `<p><b>Mật mã</b> (cipher) hiện đại đảm bảo bí mật, toàn vẹn và xác thực. Caesar: c = (m + k) mod 26 (k = 3: PARIS → SDULV), dễ bị phá. Vigenère dùng đa bảng thế; Babbage (1846) và Kasiski (1863) phá bằng phân tích thống kê. <b>Kerckhoffs</b> (1883): thiết kế mở, chỉ khóa là bí mật.</p><p>Vernam (1917) đặt nền cho OTP; Shannon (1949) đặt nền cho mật mã hiện đại; DES (chuẩn hóa 1977, khóa 56 bit); AES (2002); Diffie–Hellman (1976) mở ra mật mã khóa công khai.</p>`,
  q1: { q: "Với mật mã Caesar khóa k = 3, bản rõ PARIS cho bản mật nào?", o: ["SDULV", "QBSJT", "MXOFP", "TEVMW"], a: 0, e: "Mỗi ký tự dịch sau 3 vị trí: P→S, A→D, R→U, I→L, S→V." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Nguyên lý Kerckhoffs đề cao thiết kế mở", "Vigenère bị phá bằng phân tích thống kê của Babbage và Kasiski", "DES được chuẩn hóa năm 1977 với khóa 56 bit", "Diffie–Hellman công bố phương pháp trao đổi khóa năm 1949"], a: [0, 1, 2], e: "Diffie và Hellman công bố năm 1976." } },
{ t: "Hệ mật hoàn hảo và an toàn theo tính toán",
  s: `<p><b>Hệ mật hoàn hảo</b>: Pr(M = m | C = c) = Pr(M = m), nghĩa là bản mật không chứa thông tin về bản rõ. Theo Shannon cần khóa ngẫu nhiên, đồng xác suất, kích thước ≥ bản tin và chỉ dùng một lần. <b>OTP</b>: E(k, m) = m ⊕ k. Dùng lại khóa thì c<sub>1</sub> ⊕ c<sub>2</sub> = m<sub>1</sub> ⊕ m<sub>2</sub> (VENONA). OTP không có toàn vẹn: XOR bản mật với p thì bản rõ cũng bị XOR với p.</p><p>Thực tế dùng <b>an toàn theo tính toán</b>: kẻ tấn công hiệu quả chỉ thành công với xác suất không đáng kể (ε ≤ 2<sup>−80</sup>; ε ≥ 2<sup>−30</sup> là đáng kể).</p>`,
  q1: { q: "Hạn chế nào sau đây thuộc về OTP?", o: ["Kẻ tấn công sửa bản mật bằng phép XOR mà người nhận không phát hiện", "Không đạt được bí mật hoàn hảo", "Cần khóa ngắn hơn bản rõ", "Có thể vét cạn khóa để tìm đúng bản rõ"], a: 0, e: "OTP chỉ đảm bảo bí mật; không có cơ chế phát hiện sửa đổi." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Hệ mật hoàn hảo: bản mật không chứa thông tin về bản rõ", "Theo Shannon khóa chỉ được dùng một lần", "Xác suất ε ≥ 2^−30 được coi là không đáng kể", "An toàn tính toán chấp nhận xác suất thành công ε rất nhỏ"], a: [0, 1, 3], e: "ε ≥ 2^−30 là xác suất đáng kể; không đáng kể trong thực tế là ε ≤ 2^−80." } },
{ t: "Mã dòng và mã khối: DES, AES",
  s: `<p><b>Mã dòng</b>: c = m ⊕ PRG(k), PRG phải không thể tiên đoán. RC4 (khóa 40/128 bit) không còn an toàn; Salsa20 dùng thêm giá trị dùng một lần r. <b>Mã khối</b> xử lý khối cố định. DES: khóa 56 bit, khối 64 bit, mạng Feistel 16 vòng, đã hết hạn; 2DES bị meet-in-the-middle; 3DES dùng 2 hoặc 3 khóa. <b>AES</b>: khối 128 bit, khóa 128/192/256 bit, 10/12/14 vòng (ByteSub, ShiftRow, MixColumn).</p><p>Tấn công mã khối: vét cạn, tuyến tính, kênh bên, lỗi. Trên máy tính lượng tử, vét cạn chỉ còn căn bậc hai thời gian nên dùng AES-256.</p>`,
  q1: { q: "AES có kích thước khối dữ liệu là bao nhiêu?", o: ["56 bit", "64 bit", "128 bit", "256 bit"], a: 2, e: "AES có khối 128 bit; khóa 128, 192 hoặc 256 bit." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Mã dòng dùng PRG để sinh dãy khóa từ khóa ngắn", "RC4 vẫn được khuyến nghị sử dụng", "2DES không an toàn hơn đáng kể so với DES do tấn công meet-in-the-middle", "DES có khóa 56 bit nên có thể bị vét cạn"], a: [0, 2, 3], e: "RC4 hiện không còn an toàn." } },
{ t: "Các chế độ mã khối và sinh số ngẫu nhiên",
  s: `<p>Mã khối xác định thì không an toàn trước CPA. <b>ECB</b> mã từng khối độc lập nên lộ cấu trúc. <b>CBC</b> móc xích với IV ngẫu nhiên (IV đoán được thì bị CPA), cần padding PKCS#7. <b>CTR</b> mã hóa nonce ‖ counter, không cần padding, lặp IV là mất an toàn. Khóa dùng nhiều lần làm giảm an toàn (CBC an toàn khi q<sup>2</sup>L<sup>2</sup> ≪ X). Cả ba chế độ đều không chống được CCA.</p><p><b>Sinh khóa</b>: không dùng trực tiếp mật khẩu (entropy thấp), dùng PBKDF2 (PKCS#5); dùng nguồn ngẫu nhiên thực hoặc PRNG/DRBG (CTR-DRBG, HMAC-DRBG). PRNG tốt cần chống hồi phục.</p>`,
  q1: { q: "Hàm dẫn xuất khóa từ mật khẩu theo chuẩn PKCS#5 là gì?", o: ["PBKDF2", "RC4", "ECB", "OAEP"], a: 0, e: "PBKDF2 dùng HMAC, seed và nhiều vòng lặp để khóa trông như chuỗi bit ngẫu nhiên." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["CBC cần IV ngẫu nhiên để chống CPA", "CTR không cần padding", "Mật khẩu có entropy cao nên dùng trực tiếp làm khóa", "PRNG là hàm tất định theo seed"], a: [0, 1, 3], e: "Entropy của mật khẩu rất thấp; cần dẫn xuất khóa bằng PBKDF2." } },
{ t: "Mật mã khóa công khai: RSA, ECC và sơ đồ lai",
  s: `<p>Mật mã khóa công khai dùng cặp khóa (kU công khai, kR bí mật), dựa trên hàm một chiều và hàm cửa sập; với n bên chỉ cần n cặp khóa (đối xứng cần n(n−1)/2). <b>RSA</b>: n = p·q, φ(n) = (p−1)(q−1); e nguyên tố cùng nhau với φ(n); d thỏa e·d mod φ(n) = 1; c = m<sup>e</sup> mod n, m = c<sup>d</sup> mod n. Ví dụ p = 5, q = 11, e = 7, d = 23, m = 6 → c = 41. RSA thuần xác định nên dùng <b>RSA-OAEP</b> (padding và giá trị ngẫu nhiên).</p><p><b>ECC</b>: đường cong y<sup>2</sup> = x<sup>3</sup> + ax + b, Q = kP. Mật mã khóa công khai kém hiệu quả hơn nên dùng <b>sơ đồ lai</b>: KCK đóng gói khóa phiên (KEM), KĐX mã hóa dữ liệu (DEM). AES-128 ứng với RSA tối thiểu 3072 bit.</p>`,
  q1: { q: "Với p = 5, q = 11, e = 7, d = 23, bản rõ m = 6 cho bản mã c bằng bao nhiêu?", o: ["41", "42", "23", "6"], a: 0, e: "c = 6^7 mod 55 = 41 (theo ví dụ trên slide)." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Mật mã khóa công khai không cần chia sẻ bí mật khóa mã hóa", "Với n bên, mật mã đối xứng cần n(n−1)/2 khóa còn khóa công khai cần n cặp khóa", "RSA-OAEP bổ sung padding và giá trị ngẫu nhiên", "Mật mã khóa công khai nhanh hơn và dùng khóa ngắn hơn mật mã đối xứng"], a: [0, 1, 2], e: "Mật mã khóa công khai kém hiệu quả hơn, nên cần kết hợp trong sơ đồ lai." } }
]},
{ id: "03", title: "Mật mã học: xác thực thông điệp", topics: [
{ t: "Vấn đề xác thực thông điệp và MAC",
  s: `<p>Bản tin cần toàn vẹn, nguồn gốc tin cậy và đúng thời điểm. Các tấn công: thay thế, giả danh, phát lại, phủ nhận. <b>MAC</b> = (S, V): t = S(k, m) có kích thước cố định; V tính lại và so sánh. Ứng dụng: chuyển khoản ngân hàng, phần mềm Tripwire phát hiện file bị sửa đổi.</p><p>Đặc tính: xác định, đúng đắn, hiệu quả, an toàn (không biết k thì không tạo được t hợp lệ). MAC cung cấp toàn vẹn và xác thực danh tính, nhưng không chống từ chối và không giữ bí mật.</p>`,
  q1: { q: "Kẻ tấn công không biết khóa k thì không thể làm gì với một MAC an toàn?", o: ["Tạo được thẻ t hợp lệ cho bản tin mới", "Nghe thấy bản tin", "Sao chép bản tin", "Chặn bản tin"], a: 0, e: "Đó là yêu cầu an toàn của MAC: không thể tạo thẻ hợp lệ nếu không có k." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["MAC cho phép phát hiện bản tin bị sửa đổi", "Thẻ t có kích thước cố định, không phụ thuộc kích thước bản tin", "MAC có tính chống từ chối vì chỉ người gửi có khóa", "Tripwire dùng MAC để phát hiện file bị sửa đổi"], a: [0, 1, 3], e: "Hai bên cùng giữ khóa nên MAC không có tính chống từ chối." } },
{ t: "CBC-MAC, tấn công phát lại và mật mã có xác thực",
  s: `<p><b>CBC-MAC</b>: mã khối móc xích; rawCBC không an toàn trước tấn công chọn bản rõ nên bước cuối dùng thêm khóa thứ hai. Padding theo ISO/IEC 9797-1 bắt đầu bằng bit 1; nếu độ dài là bội của khối vẫn thêm một khối. Dùng nhiều lần một khóa làm xác suất tấn công tăng (≤ 2q<sup>2</sup>/X). Chống phát lại bằng nonce hoặc timestamp.</p><p><b>Mật mã có xác thực</b>: MAC-then-encrypt (SSL), Encrypt-and-MAC (SSH), <b>Encrypt-then-MAC</b> (IPSec, luôn chống CCA). <b>AEAD</b> (GCM, CCM, EAX) từ chối giải mã bản mã không hợp lệ. Tấn công Lucky 13 nhắm vào MAC-then-encrypt. Không dùng chung khóa cho mã mật và MAC.</p>`,
  q1: { q: "Sơ đồ kết hợp mã mật và MAC nào luôn đảm bảo an toàn trước CCA và được dùng trong IPSec?", o: ["MAC-then-encrypt", "Encrypt-and-MAC", "Encrypt-then-MAC", "Chỉ mã hóa, không MAC"], a: 2, e: "Encrypt-then-MAC xác thực cả bản mã và MAC không chứa thông tin bản rõ." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Thiết kế MAC không chống phát lại, cần thêm nonce hoặc timestamp", "Trong Encrypt-and-MAC, MAC có thể chứa thông tin về bản rõ", "Dùng chung khóa cho mã mật và MAC làm tăng rủi ro", "GCM không phải là phương pháp AEAD"], a: [0, 1, 2], e: "GCM, CCM và EAX đều là các chuẩn AEAD." } },
{ t: "Hàm băm: đặc tính và các tấn công",
  s: `<p>Hàm băm H biến bản tin bất kỳ thành digest n bit. Đặc tính: đúng đắn, hiệu quả, một chiều, chống đụng độ, ngẫu nhiên (đổi 1 bit đầu vào làm đổi hoàn toàn đầu ra). Đụng độ luôn tồn tại. Vét cạn tìm bản tin gốc hoặc bản tin đụng độ với m cho trước cần ~2<sup>n</sup>; <b>nghịch lý ngày sinh</b> cho phép tìm cặp đụng độ với ~2<sup>n/2</sup> bản tin (xác suất ~0,5). Digest càng dài càng an toàn.</p><p>MD5 (128 bit, bị tấn công 2005), SHA-1 (160 bit, bị tấn công 2017), SHA-2 và SHA-3 (224/256/384/512 bit).</p>`,
  q1: { q: "Với hàm băm 128 bit như MD5, tấn công nghịch lý ngày sinh cần khoảng bao nhiêu phép thử?", o: ["2^128", "2^64", "2^32", "128"], a: 1, e: "Cần khoảng 2^(n/2) = 2^64 bản tin." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Đổi 1 bit đầu vào làm thay đổi hoàn toàn đầu ra", "Trong hàm băm không tồn tại các bản tin đụng độ", "MD5 và SHA-1 đã bị tấn công đụng độ thành công", "Digest n bit càng lớn thì càng an toàn trước tấn công vét cạn"], a: [0, 2, 3], e: "Các bản tin đụng độ luôn tồn tại; tính chống đụng độ là việc không tìm được chúng." } },
{ t: "Sử dụng hàm băm, length extension và HMAC",
  s: `<p>Công bố mã băm để xác thực toàn vẹn dữ liệu (cần kênh công bố an toàn); chỉ phát hiện lỗi ngẫu nhiên khi truyền. Khi có tấn công chủ động, băm kèm khóa bí mật chia sẻ.</p><p>Kiến trúc Merkle–Damgård: biết h = H(m) và độ dài m thì tính được H(m ‖ Padding(m) ‖ W), nên H(k ‖ m) bị <b>length extension attack</b> (MD5, SHA-1, SHA-2). H(m ‖ k) an toàn hơn; <b>HMAC</b> (dùng ipad, opad) chống được tấn công này, nhanh hơn và cho tag lớn hơn. Hệ quả khác: H(m) = H(m*) thì H(m ‖ W) = H(m* ‖ W).</p>`,
  q1: { q: "Cách xây dựng MAC từ hàm băm nào chống được length extension attack?", o: ["H(k ‖ m)", "HMAC", "H(m)", "H(m ‖ W)"], a: 1, e: "HMAC dùng hai lần băm với ipad và opad nên chống được length extension." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["H(k ‖ m) bị length extension nếu kẻ tấn công biết độ dài k, m và h = H(k ‖ m)", "Nếu H(m) = H(m*) thì H(m ‖ W) = H(m* ‖ W) với mọi W", "HMAC sử dụng các giá trị ipad và opad", "HMAC không chống được length extension attack"], a: [0, 1, 2], e: "HMAC được thiết kế để chống length extension." } },
{ t: "Chữ ký số, bảo vệ khóa cá nhân và mật mã hậu lượng tử",
  s: `<p><b>Chữ ký số</b>: Gen(), S(sk, m), V(pk, m, sig); cung cấp xác thực, chống từ chối, toàn vẹn, không tái sử dụng, không giả mạo. Ký: băm bản tin rồi mã bằng khóa riêng; RSA: sig = H(m)<sup>d</sup> mod n, kiểm tra H(m) = sig<sup>e</sup> mod n. <b>Chữ ký mù</b> (bầu cử, tiền điện tử): người ký không biết nội dung. Bảo vệ khóa riêng: file có mật khẩu (yếu nhất), Key Store, Smart Card, USB Token; tin cậy khóa công khai qua PKI.</p><p><b>Hậu lượng tử</b>: Shor phá RSA/ECC trong thời gian đa thức; Grover giảm vét cạn còn căn bậc hai nên AES-256, SHA-512 vẫn an toàn. NIST chọn Kyber (FIPS 203), Dilithium (204), Falcon, SPHINCS+ (205).</p>`,
  q1: { q: "Thuật toán Shor trên máy tính lượng tử đe dọa trực tiếp hệ mật nào?", o: ["AES-256", "SHA-512", "RSA và ECC", "HMAC"], a: 2, e: "Shor giải bài toán phân tích thừa số và logarit rời rạc trong thời gian đa thức." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Chữ ký mù cho phép người ký không biết nội dung văn bản", "Smart Card hoặc USB Token bảo vệ khóa riêng tốt hơn file thông thường", "CRYSTALS-Dilithium là thuật toán chữ ký hậu lượng tử", "AES-256 bị bẻ khóa trong vài phút bởi máy tính lượng tử"], a: [0, 1, 2], e: "AES-256 vẫn an toàn trước Grover (độ khó còn khoảng 2^128)." } }
]},
{ id: "04", title: "Quản lý và phân phối khóa", topics: [
{ t: "Giao thức mật mã: khái niệm, đặc tính và yêu cầu",
  s: `<p><b>Giao thức</b> là chuỗi các bước mà các bên phải thực hiện để hoàn thành một tác vụ, gồm cả quy cách biểu diễn thông tin trao đổi. Hệ mật an toàn chưa đủ để trao đổi an toàn, vì còn phải tính đến các bên không trung thực. Giao thức phải không nhập nhằng, các bên phải hiểu và tuân thủ chặt chẽ, định nghĩa hành động cho mọi tình huống. Đặc tính riêng của giao thức mật mã: không bên nào thu được nhiều lợi ích hơn so với thiết kế.</p><p>Yêu cầu: <b>Forward Secrecy</b> (dữ liệu các phiên quá khứ không dùng để thỏa hiệp phiên tương lai), <b>Backward Secrecy</b> (phiên đã thực hiện vẫn an toàn nếu phiên tương lai bị thỏa hiệp), <b>Perfect Forward Secrecy</b> (khóa ngắn hạn vẫn an toàn khi khóa dài hạn về sau mất an toàn).</p>`,
  q1: { q: "Perfect Forward Secrecy trong giao thức phân phối khóa yêu cầu điều gì?", o: ["Khóa dài hạn không bao giờ thay đổi", "Khóa ngắn hạn vẫn an toàn nếu khóa dài hạn sau này không còn an toàn", "Mọi phiên dùng chung một khóa", "Chỉ dùng mật mã khóa công khai"], a: 1, e: "PFS bảo vệ các khóa ngắn hạn (khóa phiên) trước việc lộ khóa dài hạn." },
  q2: { q: "Chọn các phát biểu đúng về giao thức mật mã.", o: ["Giao thức không được nhập nhằng", "Hệ mật an toàn là đủ để trao đổi thông tin an toàn", "Giao thức phải định nghĩa hành động cho mọi tình huống có thể xảy ra", "Một bên được phép thu nhiều lợi ích hơn thiết kế của giao thức"], a: [0, 2], e: "Cần tính đến các bên không trung thực; không bên nào được lợi hơn thiết kế." } },
{ t: "Trọng tài, người phân xử, tự phân xử và các dạng tấn công",
  s: `<p><b>Trọng tài</b> (Trent) là bên thứ ba không có quyền lợi riêng, không thiên vị, được các bên tin tưởng. Hạn chế: tăng chi phí, tăng trễ, trọng tài thành “cổ chai” và có thể bị tấn công. <b>Người phân xử</b> tách giao thức làm hai: phần không cần trọng tài (hai bên ký hợp đồng rồi giao dịch) và phần chỉ chạy khi có tranh chấp (các bên trình bằng chứng). <b>Tự phân xử</b> không cần bên thứ ba, có cơ chế để phát hiện gian lận (ví dụ giao thức Bitcoin) nhưng thường phức tạp.</p><p>Tấn công giao thức: thụ động (nghe trộm), chủ động (chèn, thay thế, dùng lại thông điệp, giả mạo một bên); có thể lợi dụng điểm yếu của hệ mật hoặc của các bước thực hiện.</p>`,
  q1: { q: "Giao thức nào chỉ dùng bên thứ ba khi có tranh chấp giữa các bên?", o: ["Giao thức có trọng tài", "Giao thức có người phân xử", "Giao thức tự phân xử", "Giao thức Diffie–Hellman"], a: 1, e: "Giao thức người phân xử chỉ cần người phân xử khi có tranh chấp." },
  q2: { q: "Chọn các hạn chế của giao thức có trọng tài.", o: ["Trọng tài có thể trở thành cổ chai", "Trọng tài không thể bị tấn công", "Tăng chi phí và độ trễ", "Các bên phải tin tưởng trọng tài"], a: [0, 2, 3], e: "Trọng tài là mục tiêu tấn công hấp dẫn và là điểm tập trung của hệ thống." } },
{ t: "Phân phối khóa bí mật không tập trung và Diffie–Hellman",
  s: `<p>Khóa chính k<sub>M</sub> đã chia sẻ an toàn giữa A, B được dùng để trao đổi khóa phiên k<sub>S</sub>. <b>Giao thức 1.1</b> (A→B: ID<sub>A</sub>; B→A: E(k<sub>M</sub>, ID<sub>B</sub> ‖ k<sub>S</sub>)) bị <i>phát lại</i>: kẻ tấn công thay bản tin (2) bằng bản tin cũ, A bị lừa dùng k<sub>S</sub><sup>old</sup>. <b>Giao thức 1.2</b> thêm nonce N<sub>1</sub>, N<sub>2</sub> để chống phát lại.</p><p><b>Diffie–Hellman</b>: nhóm (p, g); A chọn X<sub>A</sub> &lt; p, Y<sub>A</sub> = g<sup>X<sub>A</sub></sup> mod p; k = Y<sub>B</sub><sup>X<sub>A</sub></sup> mod p = g<sup>X<sub>A</sub>X<sub>B</sub></sup> mod p. Ví dụ p = 71, g = 7: X<sub>A</sub> = 5 → Y<sub>A</sub> = 51; X<sub>B</sub> = 12 → Y<sub>B</sub> = 4; k = 30. Do không xác thực nên bị <i>man-in-the-middle</i>: C sinh hai cặp khóa riêng rồi tráo Y<sub>A</sub>, Y<sub>B</sub>.</p>`,
  q1: { q: "Trong ví dụ p = 71, g = 7, X_A = 5, X_B = 12 trên slide, khóa chung k bằng bao nhiêu?", o: ["51", "4", "30", "12"], a: 2, e: "k = 51^12 mod 71 = 4^5 mod 71 = 30." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Giao thức 1.1 dễ bị tấn công phát lại vì không có yếu tố chống phát lại", "Giao thức 1.2 dùng nonce N1, N2 để chống phát lại", "Diffie–Hellman thuần túy chống được man-in-the-middle", "Khóa chung trong DH là g^(X_A·X_B) mod p"], a: [0, 1, 3], e: "DH không xác thực các bên nên cần kết hợp với xác thực để chống MITM." } },
{ t: "Phân phối khóa tập trung với KDC",
  s: `<p>KDC (Key Distribution Centre) chia sẻ khóa k<sub>A</sub> với A, k<sub>B</sub> với B, sinh và phân phối khóa phiên k<sub>S</sub>. <b>Giao thức 2.1</b> không có yếu tố chống phát lại. <b>2.2 Needham–Schroeder</b>: thêm nonce N<sub>1</sub> trong bản tin KDC→A, rồi B thử thách A bằng N<sub>2</sub> và A trả lời f(N<sub>2</sub>) với f(x) ≠ x; nếu bước (4) bị thay bằng khóa cũ, B sẽ từ chối vì giá trị f không khớp.</p><p><b>2.3 Denning</b> thêm nhãn thời gian T do KDC tạo; bên nhận kiểm tra |t − T| &lt; Δt nên cần đồng bộ đồng hồ. <b>2.4 Kehne</b> dùng nhãn thời gian T<sub>B</sub> do chính B tạo, nên B chỉ đối chiếu với đồng hồ của mình và không phụ thuộc đồng bộ giữa các bên.</p>`,
  q1: { q: "Vì sao dùng nhãn thời gian T_B của B (Kehne) tốt hơn T của KDC (Denning)?", o: ["T_B ngắn hơn T", "B kiểm tra T_B bằng chính đồng hồ của mình nên không phụ thuộc đồng bộ giữa các bên", "KDC không cần tham gia giao thức", "Không cần dùng khóa phiên"], a: 1, e: "Ở Denning, mất đồng bộ đồng hồ giữa các bên làm giao thức mất an toàn." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Giao thức 2.1 đã có nonce nên chống được phát lại", "Trong Needham–Schroeder, hàm f phải thỏa f(x) ≠ x", "Giao thức Denning dùng nhãn thời gian nên cần đồng bộ đồng hồ", "Needham–Schroeder dùng nonce để chống phát lại"], a: [1, 2, 3], e: "Giao thức 2.1 không có nonce hay nhãn thời gian nên bị phát lại." } },
{ t: "Phân phối khóa công khai và PKI",
  s: `<p>Alice cần chắc chắn k<sub>U<sub>B</sub></sub> đúng là khóa công khai của Bob. Có thể trao đổi trực tiếp (danh sách tin cậy), dùng PKA ký khóa công khai (giao thức 4.1; 4.2 thêm nhãn thời gian T), hoặc dùng <b>CA</b> phát hành chứng chỉ Cert = ID ‖ kU ‖ Time ‖ sig(kR<sub>CA</sub>, ID ‖ kU ‖ Time).</p><p><b>PKI</b> gồm RA (chứng thực thông tin đăng ký), CA (phát hành, quản lý), CR (lưu trữ, chứng thực), EE (đối tượng dùng). <b>X.509</b>: Version, Serial, Algorithm, Issuer, Validity, Subject, Public Key, Signature. Xác thực chứng chỉ: tên khớp, hạn dùng, CA tin cậy, trạng thái thu hồi, chữ ký. Thu hồi bằng <b>CRL</b> (lớn, không cập nhật liên tục) hoặc <b>OCSP</b> (trực tuyến). Kiến trúc: đơn CA, danh sách tin cậy, phân cấp (Root CA offline); chuỗi xác thực từ chối nếu một bước thất bại.</p><p>Lưu ý: dùng giao thức chuẩn (IPSec, TLS, Kerberos); không dùng cùng khóa cho hai chiều hoặc hai mục đích; thông báo lỗi không nêu cụ thể nguyên nhân.</p>`,
  q1: { q: "Trong PKI, thành phần nào lưu trữ và chứng thực chứng chỉ số?", o: ["RA", "CA", "CR", "EE"], a: 2, e: "CR (Certificate Repository) lưu trữ, chứng thực; RA xác minh đăng ký; CA phát hành; EE là đối tượng dùng." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Xác thực chứng chỉ cần kiểm tra hạn sử dụng", "CRL luôn được cập nhật liên tục", "OCSP cho phép kiểm tra trạng thái chứng chỉ trực tuyến", "Root CA thường được giữ ở phân vùng mạng offline"], a: [0, 2, 3], e: "CRL có kích thước lớn và không cập nhật liên tục." } }
]},
{ id: "05", title: "Xác thực danh tính", topics: [
{ t: "Yếu tố xác thực và các tấn công vào mật khẩu",
  s: `<p>Xác thực danh tính liên kết chủ thể thật với danh tính truy cập. Các yếu tố: <b>tri thức</b> (biết), <b>tài sản</b> (có), <b>sinh trắc</b> (là), <b>vị trí</b>; dùng hơn một yếu tố là <b>MFA</b>. Con người không nhớ nổi nhiều mật khẩu mạnh nên dùng lại; lộ một tài khoản có thể kéo theo tài khoản khác. Không đổ lỗi cho người dùng; hỗ trợ bằng trình quản lý mật khẩu (Master Password), thẻ U2F (giảm phishing), bật 2FA.</p><p>Tấn công thụ động: nhìn trộm, keylogging, chặn gói tin, kênh bên. Chủ động: đoán và thử, giả mạo server/client, tấn công máy chủ. <b>Online attack</b>: P ≥ (T × G)/N (G tốc độ dò, T thời gian, N số mật khẩu có thể tạo); giảm thiểu bằng mật khẩu dài và giới hạn số lần thử.</p>`,
  q1: { q: "Yếu tố xác thực “What the entity has” là yếu tố nào?", o: ["Tri thức", "Tài sản", "Sinh trắc", "Vị trí"], a: 1, e: "Tri thức: biết; tài sản: có; sinh trắc: là; vị trí: ở đâu." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Nên đổ lỗi cho người dùng khi họ sơ ý bị phishing", "Dùng lại mật khẩu khiến lộ một tài khoản có thể kéo theo tài khoản khác", "Thẻ U2F giúp giảm nguy cơ bị phishing", "Giới hạn số lần thử xác thực giúp giảm thiểu tấn công đoán và thử"], a: [1, 2, 3], e: "Hệ thống cần hỗ trợ người dùng không hành động sai thay vì đổ lỗi cho họ." } },
{ t: "Lưu trữ mật khẩu: băm, salt và pepper",
  s: `<p><b>Offline attack</b> xảy ra khi lộ CSDL. Lưu rõ là nguy hiểm nhất; lưu bản mã thì lộ khóa là lộ tất cả; lưu mã băm có tính xác định nên lộ việc hai người dùng chung mật khẩu và bị <b>rainbow table</b>. Dùng <b>salt</b>: lưu [salt, Hash(password ‖ salt)]; mỗi bảng tra cứu chỉ ứng một salt nên Hash(m, salt<sub>1</sub>) ≠ Hash(m, salt<sub>2</sub>).</p><p>Ví dụ Linux <code>/etc/shadow</code>: <code>$id$salt$hash</code> (1: MD5, 2: Blowfish, 5: SHA-256, 6: SHA-512). Nâng cao: băm nhiều lần để làm chậm, thêm <b>pepper</b> lưu bí mật, ưu tiên bcrypt, scrypt, PBKDF2.</p>`,
  q1: { q: "Trong /etc/shadow, tiền tố $6$ cho biết thuật toán băm nào?", o: ["MD5", "Blowfish", "SHA-256", "SHA-512"], a: 3, e: "Mã 1: MD5, 2: Blowfish, 5: SHA-256, 6: SHA-512." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Mỗi bảng tra cứu chỉ ứng với một giá trị salt", "Pepper được lưu bí mật", "Băm nhiều lần làm chậm quá trình dò tìm", "Salt biến mọi mật khẩu yếu thành an toàn tuyệt đối"], a: [0, 1, 2], e: "Mật khẩu dễ đoán vẫn dễ bị tìm ra dù có salt." } },
{ t: "Khôi phục mật khẩu, chính sách và giao thức PAP, CHAP, EAP",
  s: `<p>Khôi phục mật khẩu (mã xác thực qua email/SMS) không được dễ vượt qua hơn xác thực. Câu hỏi bí mật không an toàn: tài khoản Yahoo của Sarah Palin (2008) và Hotmail của Mitt Romney (2012) bị đánh cắp. Chính sách: độ dài tối thiểu, ký tự bắt buộc, đổi định kỳ, hạn chế dùng lại, giới hạn số lần thử; luôn cân nhắc tính tiện lợi.</p><p><b>PAP</b>: U→S: ID ‖ Password (không an toàn). <b>CHAP</b>: S gửi challenge ngẫu nhiên; U gửi ID ‖ Hash(ID ‖ Hash(Password) ‖ Challenge). <b>EAP</b> có khoảng 40 biến thể (EAP-MD5 tương tự CHAP, EAP-TLS, PEAP, EAP-POTP, EAP-PSK). Xác thực hai chiều đối xứng: A→B: ID<sub>A</sub>; B→A: N<sub>B</sub>; A→B: f(K<sub>S</sub>, N<sub>B</sub>) ‖ N<sub>A</sub>; B→A: f(K<sub>S</sub>, N<sub>A</sub>).</p>`,
  q1: { q: "CHAP an toàn hơn PAP vì lý do chính nào?", o: ["Dùng mật khẩu dài hơn", "Server gửi challenge ngẫu nhiên và mật khẩu không được gửi trực tiếp", "Không cần server", "Chỉ dùng sinh trắc"], a: 1, e: "PAP gửi ID ‖ Password trực tiếp, còn CHAP gửi giá trị băm có challenge." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Cơ chế khôi phục mật khẩu không được dễ vượt qua hơn cơ chế xác thực", "PAP truyền ID và mật khẩu và không an toàn", "EAP-MD5 có cơ chế tương tự CHAP", "Câu hỏi bí mật luôn an toàn vì chỉ chủ tài khoản biết đáp án"], a: [0, 1, 2], e: "Các vụ Palin (2008) và Romney (2012) cho thấy câu hỏi bí mật dễ bị khai thác." } },
{ t: "Giao thức zero-knowledge (Feige–Fiat–Shamir)",
  s: `<p><b>ZKP</b> cho phép <i>Peggy</i> chứng minh cho <i>Victor</i> rằng mình nắm thông tin mà không làm lộ nó; giao thức phải chống <i>Eve</i> (nghe lén) và <i>Mallory</i> (nghe lén, sửa, phát lại).</p><p><b>FFS</b>: Peggy chọn p, q, n = p·q, s với UCLN(s, n) = 1, v = s<sup>2</sup> mod n, công bố (n, v). Mỗi vòng: P→V: x = r<sup>2</sup> mod n (r ngẫu nhiên); V→P: b ∈ {0, 1}; P→V: y = r·s<sup>b</sup> mod n; V kiểm tra y<sup>2</sup> ≡ x·v<sup>b</sup> (mod n). Mallory đoán trước b thì thành công 1/2 mỗi vòng, tức 2<sup>−n</sup> sau n vòng (<i>soundness</i>); Peggy biết s thì qua mọi vòng (<i>completeness</i>). Nguy cơ: dùng lại r, Mafia, Chess Grandmaster, Terrorist.</p>`,
  q1: { q: "Xác suất Mallory (không biết s) vượt qua một vòng FFS bằng cách đoán bit b là bao nhiêu?", o: ["1/4", "1/2", "1/n", "1"], a: 1, e: "b ∈ {0, 1} nên đoán đúng với xác suất 1/2 mỗi vòng, còn 2^−n sau n vòng." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Victor kiểm tra y² ≡ x·v^b (mod n)", "Peggy nên dùng lại cùng giá trị r ở mọi vòng để tiết kiệm", "Nếu không biết s, xác suất giả mạo thành công tối đa là 2^−n sau n vòng", "Eve nghe được mọi bộ (x, y, b) vẫn không suy ra được s"], a: [0, 2, 3], e: "Dùng lại r làm lộ s; tính căn bậc hai rời rạc là bài toán khó." } },
{ t: "OTP: S/Key, HOTP, TOTP và SMS OTP",
  s: `<p>Mật khẩu một lần (<b>OTP</b>) chỉ dùng cho một phiên hoặc giao dịch. <b>S/Key</b> (RFC 1760): server chọn W, băm n lần, lưu H<sup>n</sup>; client giữ H<sup>n−1</sup>…H<sup>1</sup>; xác thực bằng cách gửi H<sup>n−1</sup>, server băm lại, so với H<sup>n</sup> rồi thay bằng H<sup>n−1</sup>. <b>HOTP</b> (RFC 4226): HS = HMAC-SHA-1(K, C), dùng Dynamic Truncation (offset từ 4 bit thấp của S[19]), D = Snum mod 10<sup>k</sup>; lệch bộ đếm thì đồng bộ lại. <b>TOTP</b> (RFC 6238): C = (UnixTime − T<sub>0</sub>)/X, chấp nhận trong khoảng sai số.</p><p><b>SMS OTP</b> không an toàn: nghe lén, giả trạm BTS, lỗ hổng SS7 (không xác thực; dùng MSISDN, IMSI, HLR, MSC để chuyển hướng tin nhắn tới Fake MSC).</p>`,
  q1: { q: "Ở S/Key, server làm gì với giá trị H^(n−1) mà client gửi?", o: ["So sánh trực tiếp với H^n", "Băm một lần rồi so với H^n trong CSDL", "Giải mã bằng khóa riêng", "Lưu mà không kiểm tra"], a: 1, e: "Hash(H^(n−1)) phải bằng H^n; sau đó server thay H^n bằng H^(n−1)." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["HOTP dùng HMAC-SHA-1 với bộ đếm C", "TOTP thay bộ đếm C bằng giá trị dựa trên thời gian", "SMS OTP an toàn tuyệt đối vì gửi riêng cho người dùng", "S/Key dùng các giá trị băm theo thứ tự ngược H^(n−1), H^(n−2)…"], a: [0, 1, 3], e: "SMS OTP có thể bị nghe lén, giả BTS hoặc tấn công qua SS7." } },
{ t: "Sinh trắc học, tấn công chuyển tiếp và SSO",
  s: `<p><b>Sinh trắc</b> xác thực dựa trên đặc điểm sinh trắc hoặc hành vi (không phải chủ đề mới: Bertillon 1882, vân tay Galton/Henry 1900, AFIS 1965, IAFIS ~2000): vân tay, lòng bàn tay, khuôn mặt, mống mắt, vành tai, mạch máu. Thách thức: số lớp lớn, nhiễu khi thu thập, mức độ phổ biến, hiệu năng, tấn công vào hệ thống, riêng tư (theo dõi, thông tin y tế, ADN).</p><p><b>Tấn công chuyển tiếp</b> (relay) vượt MFA: website giả lấy mật khẩu, kẻ tấn công đăng nhập vào website thật, website thật gửi OTP, website giả đòi OTP rồi chuyển cho kẻ tấn công. <b>SSO</b>: đăng nhập một lần để truy cập nhiều ứng dụng trong một phiên (OpenID Connect, CAS, SAML, Google Sign-In, Facebook Login).</p>`,
  q1: { q: "Kịch bản website giả mạo lấy mật khẩu rồi đòi OTP để dùng ngay trên website thật là tấn công nào?", o: ["Tấn công từ điển", "Tấn công chuyển tiếp (relay)", "Tấn công vét cạn", "Tấn công SQL injection"], a: 1, e: "Kẻ tấn công chuyển tiếp các yếu tố xác thực sang website thật theo thời gian thực." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["SSO cho phép đăng nhập một lần để truy cập nhiều ứng dụng trong một phiên", "Tấn công chuyển tiếp có thể vượt qua xác thực hai yếu tố mật khẩu + OTP", "Sinh trắc học không có vấn đề về riêng tư", "OpenID Connect và SAML là các giải pháp SSO"], a: [0, 1, 3], e: "Dữ liệu sinh trắc có thể bị dùng để theo dõi hoạt động và có thể tiết lộ thông tin y tế." } }
]},
{ id: "07", title: "An toàn cho tiến trình (Memory Safety)", topics: [
{ t: "Tiến trình, bộ nhớ ảo và kiến trúc x86",
  s: `<p><b>Tiến trình</b> là chương trình đang thực thi, gồm vùng nhớ, con trỏ lệnh, thanh ghi CPU và PCB. Mỗi tiến trình dùng <b>bộ nhớ ảo</b> do HĐH/CPU ánh xạ sang bộ nhớ vật lý: cách ly giữa các tiến trình và tối thiểu hóa quyền. Bố cục x86 32-bit (từ cao xuống thấp): Kernel, cmdline &amp; env, stack, heap, BSS, data, text.</p><p>x86: tập lệnh CISC, little-endian; thanh ghi đa dụng EAX, EBX, ECX, EDX, ESI, EDI; ESP (đỉnh stack), EBP (đáy stack frame), EIP (con trỏ lệnh). Cú pháp: <code>%reg</code>, <code>$const</code>, <code>8(%ebp)</code>. <code>push</code> giảm ESP rồi cất giá trị; <code>pop</code> lấy giá trị rồi tăng ESP.</p>`,
  q1: { q: "Lệnh push làm giá trị thanh ghi ESP thay đổi như thế nào?", o: ["Tăng lên", "Giảm đi", "Không đổi", "Gán bằng EBP"], a: 1, e: "Stack tăng trưởng về địa chỉ thấp nên push giảm ESP." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Tiến trình truy cập trực tiếp vào địa chỉ bộ nhớ vật lý", "Little-endian: byte có ý nghĩa thấp nằm ở ô nhớ có địa chỉ thấp", "EIP là thanh ghi con trỏ lệnh", "Vùng heap được quản lý bởi các hàm cấp phát động như malloc, calloc"], a: [1, 2, 3], e: "Tiến trình dùng địa chỉ ảo; HĐH/CPU ánh xạ sang địa chỉ vật lý." } },
{ t: "Stack frame và quy ước gọi hàm",
  s: `<p>Quy ước x86: tham số đẩy vào stack theo thứ tự ngược với khai báo; kết quả trả về trong EAX; EAX, ECX, EDX là caller-saved. <b>Hàm gọi</b>: đẩy tham số, <code>call</code> cất EIP (gọi là <b>RIP</b>) vào stack rồi nhảy tới hàm được gọi. <b>Hàm được gọi</b>: <code>push %ebp</code> (cất <b>SFP</b>), <code>mov %esp, %ebp</code>, <code>sub</code> để cấp phát biến cục bộ.</p><p>Trả về: <code>mov %ebp, %esp</code> (xóa biến cục bộ), <code>pop %ebp</code> (khôi phục EBP từ SFP), <code>ret</code> (lấy RIP gán cho EIP); hàm gọi <code>add</code> vào ESP để dọn tham số. Stack frame từ địa chỉ cao xuống thấp: tham số, RIP, SFP, biến cục bộ; mảng lưu từ địa chỉ thấp lên cao.</p>`,
  q1: { q: "Lệnh ret thực hiện việc gì?", o: ["Cất EBP vào stack", "Lấy giá trị RIP ở đỉnh stack gán cho EIP", "Cấp phát biến cục bộ", "Gán giá trị trả về cho EAX"], a: 1, e: "ret lấy RIP trên đỉnh stack gán cho EIP, quay về lệnh tiếp theo của hàm gọi." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Giá trị trả về của hàm được gán vào thanh ghi EBX", "Lệnh call cất RIP vào stack", "Tham số được đẩy vào stack theo thứ tự ngược với khai báo", "SFP là giá trị EBP cũ dùng để khôi phục EBP khi hàm trả về"], a: [1, 2, 3], e: "Giá trị trả về được gán vào EAX." } },
{ t: "Tràn bộ đệm và code injection",
  s: `<p><b>Tràn bộ đệm</b>: ghi vào bộ đệm nhiều hơn khả năng chứa (C/C++ không kiểm soát kích thước). Ví dụ <code>strcpy(buffer[4], "AuthMe!")</code> ghi đè SFP, khiến EBP = 0x0021654d và gây segmentation fault; hoặc ghi đè biến <code>authenticated</code> kề bên. <b>Code injection</b>: tìm lỗ hổng, ghi mã độc, ghi đè RIP bằng địa chỉ mã độc, hàm trả về thì mã độc chạy. <b>Shellcode</b> thường gọi <code>execve("/bin//sh")</code>.</p><p>Với <code>char name[20]; gets(name);</code>: 20 byte của name + 4 byte SFP = 24 byte đệm, 4 byte kế tiếp ghi đè RIP. Trên <b>heap</b>: heap overflow (ghi đè dữ liệu và con trỏ kề), use-after-free (dùng vùng nhớ đã free), ghi đè con trỏ vtable của C++ để chuyển hướng gọi phương thức.</p>`,
  q1: { q: "Với char name[20] trên stack x86 32-bit, cần bao nhiêu byte đệm trước khi 4 byte tiếp theo ghi đè RIP?", o: ["20", "24", "28", "4"], a: 1, e: "20 byte của name cộng 4 byte SFP là 24 byte." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["gets() tự kiểm soát kích thước dữ liệu đầu vào", "Dữ liệu tràn có thể ghi đè các biến cục bộ khác như authenticated", "Code injection ghi mã độc rồi ghi đè RIP để trỏ tới mã đó", "Use-after-free là truy cập vùng nhớ đã được giải phóng"], a: [1, 2, 3], e: "gets() không kiểm tra kích thước; nên dùng fgets()." } },
{ t: "Phòng chống tràn bộ đệm: canary, NX, ASLR, PAC",
  s: `<p>Phòng chống: hàm an toàn (<code>fgets</code>, <code>strlcpy</code>, <code>strlcat</code>); Stack Shield; <b>canary</b> (Stack Guard) phát hiện ghi liên tục đè qua giá trị canh giữ; có thể bị rò rỉ (lỗ hổng xâu định dạng), bị vòng tránh (heap, vtable) hoặc đoán. <b>Non-executable pages</b> không cho thực thi mã trên stack nhưng vẫn bị <b>return-to-libc</b> (RIP nhảy tới system()) và <b>ROP</b> (chuỗi gadget kết thúc bằng ret).</p><p><b>PAC</b> dùng 22 bit địa chỉ không dùng của con trỏ 64 bit để lưu mã xác thực (ARM v8.3). <b>ASLR</b> đặt ngẫu nhiên stack, heap, code mỗi lần chạy; trang nhớ 4KB nên trên 32 bit cần đoán 32 − 12 = 20 bit (64 bit: 48 − 12 = 36 bit). Nên kết hợp nhiều lớp (ASLR + non-executable pages; iOS còn có sandbox), vì các kỹ thuật không được kích hoạt mặc định thường bị khai thác.</p>`,
  q1: { q: "ASLR trên hệ thống 32 bit với trang nhớ 4KB (12 bit địa chỉ trong trang) cần kẻ tấn công đoán bao nhiêu bit?", o: ["12", "20", "32", "36"], a: 1, e: "32 − 12 = 20 bit; với địa chỉ 48 bit là 36 bit." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["Canary giúp phát hiện dữ liệu tràn đè lên giá trị canh giữ trước RIP", "Non-executable pages ngăn được cả return-to-libc và ROP", "ROP dùng các gadget, thường kết thúc bằng lệnh ret", "Kết hợp ASLR và non-executable pages buộc kẻ tấn công phải tìm nhiều lỗ hổng"], a: [0, 2, 3], e: "Non-executable pages không ngăn kẻ tấn công dùng mã đã nạp sẵn như libc." } },
{ t: "Xâu định dạng, tràn số nguyên và lập trình an toàn",
  s: `<p><b>Xâu định dạng</b>: <code>printf(buf)</code> với buf do người dùng nhập; <code>%d</code>, <code>%x</code> đọc dữ liệu stack, <code>%s</code> đọc tới ký tự kết thúc xâu, <code>%n</code> ghi số byte đã in vào bộ nhớ. Sửa: <code>printf(&quot;%s&quot;, buf)</code>. <b>Tràn số nguyên</b>: giá trị ngoài dải biểu diễn; <code>len = −1</code> qua kiểm tra <code>len &gt; 1024</code> rồi thành 0xffffffff khi vào memcpy; <code>malloc(len * sizeof(int))</code> với n = 0x4000 cho 4n = 0. <b>Serialization</b>: không kiểm soát luồng byte khi deserialize (lỗ hổng Log4j, 11/2021, qua JNDI).</p><p>Ngôn ngữ memory-safe (Java, C#, Python, Go, Rust) kiểm tra biên tự động. <b>An toàn không gian</b>: truy cập hợp lệ khi b ≤ p ≤ e − s. <b>An toàn thời gian</b>: chỉ truy cập vùng nhớ đã cấp phát và khởi tạo; gán NULL cho con trỏ sau free. Nguyên tắc: không tin những gì không do mình tạo, kiểm tra mọi đầu vào, dùng hàm xâu an toàn (fgets, strlcpy), std::string.</p>`,
  q1: { q: "Cách sửa an toàn cho lệnh printf(buf), với buf do người dùng nhập, là gì?", o: ["printf(&quot;%s&quot;, buf)", "printf(buf, buf)", "printf(&quot;%n&quot;, buf)", "Không cần sửa"], a: 0, e: "Xâu định dạng phải là hằng, dữ liệu người dùng chỉ là tham số." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["len = −1 vượt qua kiểm tra len > 1024 rồi thành 0xffffffff khi truyền vào memcpy", "Gán NULL cho con trỏ sau khi free là không cần thiết", "%n trong printf cho phép ghi vào bộ nhớ", "An toàn không gian yêu cầu b ≤ p ≤ e − s"], a: [0, 2, 3], e: "Gán NULL sau free giúp tránh dùng lại vùng nhớ đã giải phóng (an toàn thời gian)." } }
]},
{ id: "09", title: "An toàn an ninh mạng", topics: [
{ t: "Mạng máy tính, kiến trúc phân tầng và định danh",
  s: `<p>Mạng máy tính gồm các máy tính kết nối qua thiết bị mạng và đường truyền (hữu tuyến, vô tuyến) theo một kiến trúc: hình trạng mạng và giao thức mạng. <b>Kiến trúc phân tầng</b> chia chức năng thành các tầng, dễ thiết kế và nâng cấp. OSI mang tính tham chiếu; TCP/IP dùng thực tế: ứng dụng (Web, Email, FTP), giao vận (TCP tin cậy, UDP không tin cậy), liên mạng (IP, định tuyến, chuyển tiếp), liên kết dữ liệu, vật lý.</p><p>Định danh: tên miền (tầng ứng dụng), số hiệu cổng 1–65535 (Web 80, DNS 53, SMTP 25, POP 110, IMAP 143), địa chỉ IP (IPv4 32 bit, IPv6 128 bit), địa chỉ MAC 48 bit chỉ dùng trong mạng nội bộ. <b>Đóng gói</b>: bên gửi thêm tiêu đề ở mỗi tầng rồi chuyển xuống; bên nhận tách tiêu đề và chuyển lên tầng trên.</p>`,
  q1: { q: "Địa chỉ MAC có kích thước và phạm vi sử dụng nào?", o: ["32 bit, toàn Internet", "48 bit, chỉ trong mạng nội bộ", "128 bit, mạng nội bộ", "48 bit, toàn Internet"], a: 1, e: "Địa chỉ MAC 48 bit, biểu diễn hexa, chỉ dùng trong mạng nội bộ." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["IPv6 dùng địa chỉ 64 bit", "Web dùng cổng 80 mặc định", "DNS dùng cổng 53", "Bên gửi đóng gói dữ liệu bằng cách thêm tiêu đề ở mỗi tầng"], a: [1, 2, 3], e: "IPv6 dùng địa chỉ 128 bit; IPv4 dùng 32 bit." } },
{ t: "Các giao thức IP, ICMP, định tuyến, UDP, TCP, DNS và HTTP",
  s: `<p><b>IP</b> (tầng liên mạng) thống nhất định danh và cách đóng gói, không phụ thuộc hạ tầng vật lý. <b>ICMP</b> báo lỗi khi chuyển tiếp gói IP; <code>ping</code> dùng echo request/reply. <b>Giao thức định tuyến</b> (RIP, OSPF, BGP) chạy trên bộ định tuyến, trao đổi tuyến đường để tìm đường tốt nhất.</p><p><b>UDP</b>: không liên kết, không tin cậy, nhanh, đơn giản (DHCP, SNMP). <b>TCP</b>: hướng liên kết (bắt tay 3 bước SYN, SYN/ACK, ACK; truyền dữ liệu; đóng liên kết bằng FIN), tin cậy (Seq#, ACK, phát lại). <b>DNS</b> (cổng 53, UDP/TCP; DoH cổng 443) phân giải tên miền thành IP, máy trạm không kiểm tra tính tin cậy của câu trả lời. <b>HTTP</b> (cổng 80, trên TCP) trao đổi request/response dạng ASCII.</p>`,
  q1: { q: "Giao thức nào là không liên kết và không tin cậy?", o: ["TCP", "UDP", "HTTP", "BGP"], a: 1, e: "UDP gửi ngay dữ liệu và không phát lại khi có lỗi." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["DNS bắt buộc xác thực câu trả lời của máy chủ", "Lệnh ping dùng ICMP echo request và echo reply", "BGP là một giao thức định tuyến", "TCP thiết lập liên kết bằng bắt tay 3 bước"], a: [1, 2, 3], e: "Máy trạm DNS không kiểm tra tính tin cậy của câu trả lời, nên có thể bị giả mạo." } },
{ t: "Tấn công vào IP, định tuyến, TCP và DNS",
  s: `<p>IP không mã hóa, không xác thực toàn vẹn và địa chỉ nguồn, nên bị nghe lén, sửa đổi, giả danh. RIPv1 không xác thực; RIPv2, OSPF, BGP dùng khóa chia sẻ trước (thường không ngẫu nhiên). OSPF bị tấn công bằng LSA giả (black-hole). <b>BGP hijacking</b>: 02/2008 Pakistan Telecom quảng bá 208.65.153.0/24 nên theo longest matching, YouTube (208.65.152.0/22) không truy cập được khoảng 2 giờ.</p><p>Tấn công TCP: <b>RST injection</b> (biết cổng và Seq), <b>data injection</b>, <b>TCP spoofing</b>: Mitnick (1992) lợi dụng X-terminal sinh Seq dự đoán được (Seq<sub>i</sub> = Seq<sub>i−1</sub> + 128.000), kết hợp SYN flood để máy tin cậy không gửi RST. <b>DNS cache poisoning</b>: gửi truy vấn ranN.bank.com rồi chèn phản hồi giả có đúng QID (UDP) tới trước phản hồi thật, kèm bản ghi giả TTL dài.</p>`,
  q1: { q: "Tấn công của Mitnick lợi dụng điểm yếu nào của X-terminal?", o: ["Không dùng mật khẩu", "Giá trị Seq của TCP sinh ra dự đoán được", "Dùng giao thức UDP", "Không có địa chỉ IP"], a: 1, e: "Seq được tính bằng Seq trước + 128.000 nên kẻ tấn công đoán được số Seq." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["RIPv1 hỗ trợ xác thực bằng khóa ngẫu nhiên mạnh", "Pakistan Telecom quảng bá prefix /24 cụ thể hơn nên router chọn theo longest matching", "IP không xác thực địa chỉ nguồn", "RST injection cần biết số hiệu cổng và Sequence Number phù hợp"], a: [1, 2, 3], e: "RIPv1 không hỗ trợ cơ chế xác thực." } },
{ t: "Giao thức bảo mật: IPSec, SSL/TLS và HTTPS",
  s: `<p><b>IPSec</b> (IPv4/IPv6, RFC 4301): bảo mật (DES, 3DES, AES), xác thực (HMAC MD5, SHA-1), chống phát lại, xác thực các bên, kiểm soát truy cập. Đóng gói: <b>AH</b> (xác thực), <b>ESP</b> (bảo mật), ESP-ICV (cả hai). <b>SSL/TLS</b> nằm giữa tầng giao vận và ứng dụng, chạy trên TCP (DTLS chạy trên UDP); gồm giao thức <i>bắt tay</i> (dùng mật mã khóa công khai trao đổi khóa bí mật) và giao thức <i>bảo vệ dữ liệu</i> (dùng khóa đó).</p><p><b>HTTPS</b> = HTTP + SSL/TLS, cổng 443 (IMAP 993, POP3 995, SMTP 465, FTPS 990/989). Trình duyệt kiểm tra chứng thư: cấp cho đúng tên miền, bởi tổ chức tin cậy, còn hạn, chưa bị thu hồi, không giả mạo. HTTPS chỉ bảo vệ dữ liệu khi truyền; không bảo đảm website an toàn.</p>`,
  q1: { q: "Giao thức bắt tay (handshake) trong SSL/TLS có vai trò gì?", o: ["Mã hóa dữ liệu ứng dụng bằng khóa công khai", "Thiết lập kết nối và trao đổi khóa bí mật bằng mật mã khóa công khai", "Nén dữ liệu", "Định tuyến gói tin"], a: 1, e: "Khóa bí mật trao đổi ở bắt tay được dùng ở giao thức bảo vệ dữ liệu (record)." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["AH cung cấp xác thực thông điệp, ESP cung cấp bảo mật", "HTTPS bảo đảm mọi website là an toàn", "HTTPS dùng cổng 443", "DTLS là phiên bản tương tự TLS chạy trên UDP"], a: [0, 2, 3], e: "HTTPS chỉ bảo vệ dữ liệu khi truyền, không đảm bảo website an toàn." } },
{ t: "Do thám và các dạng tấn công DoS",
  s: `<p><b>Do thám</b> (chủ động có tương tác, bị động không tương tác) thu thập thông tin về tổ chức và hệ thống: công cụ tìm kiếm (Google, Shodan, Censys), mạng xã hội, website, WHOIS, DNS, traceroute, kỹ nghệ xã hội, <i>Ping Sweep</i> (ICMP echo) tìm nút hoạt động, quét cổng (TCP SYN Scan), xác định hệ điều hành.</p><p><b>DoS</b> ngăn dịch vụ tới người dùng: vật lý; băng thông (Smurf, DNS Amplification, UDP Flood); tài nguyên (Teardrop, TCP SYN Flood, HTTP Flood, DHCP Starvation); lỗ hổng phần mềm (Ping of Death). SYN Flood gửi SYN nhưng không hoàn thành bước 3, server giữ tài nguyên chờ ACK. DNS Amplification: query ~60 byte với IP nguồn giả là nạn nhân, response ~3000 byte. <b>DDoS</b> dùng botnet (C&amp;C, slave); <b>DRDoS</b> dùng reflector, che giấu nguồn, không cần nhiều bot. Khó phòng chống vì kỹ thuật đơn giản, Internet không thiết kế chống DoS, dễ chiếm máy (IoT: Mirai), khó phân biệt lưu lượng và thiếu phối hợp giữa các ISP.</p>`,
  q1: { q: "Kỹ thuật nào dùng ICMP Echo Request để xác định các nút mạng đang hoạt động?", o: ["Ping Sweep", "SYN Flood", "DNS Amplification", "Port Scanning"], a: 0, e: "Nút nào trả ICMP Echo Reply là nút đang hoạt động." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["DRDoS dùng địa chỉ nguồn giả là địa chỉ nạn nhân khi gửi tới reflector", "DNS Amplification lợi dụng response lớn hơn nhiều query", "SYN Flood hoàn thành đủ bắt tay 3 bước với server", "Quét cổng thực hiện bằng TCP SYN Scan"], a: [0, 1, 3], e: "SYN Flood không gửi ACK ở bước 3 nên server giữ tài nguyên chờ." } },
{ t: "Phòng chống DoS, tường lửa và IDPS",
  s: `<p>Phòng chống DoS: phần cứng (phòng máy, camera); lỗ hổng phần mềm (kiểm thử xâm nhập, vá lỗi); tài nguyên tính toán (firewall, IDPS, cấu hình hệ thống, CAPTCHA); băng thông (mở rộng băng thông, cân bằng tải; ISP chặn từ nguồn, truy vết, phát hiện botnet).</p><p><b>Tường lửa</b> thi hành chính sách cho phép/từ chối theo giao thức, địa chỉ, nội dung; hạn chế tấn công từ ngoài và giữa các phân vùng; ghi nhật ký. Không làm được: nguy cơ từ bên trong, lưu lượng không đi qua, lưu lượng mã hóa, tấn công chưa biết, mã độc. Kiến trúc: <i>network-based</i> (phạm vi rộng), <i>host-based</i> (một nút), <i>application</i> (kiểm soát cả lưu lượng mã hóa tới dịch vụ, luật phức tạp). <b>IDPS</b> giám sát chuỗi gói tin và hành vi (tường lửa xử lý từng gói). Phát hiện: lạm dụng (signature, vulnerability signature) hoặc bất thường (ngưỡng, thống kê, học máy).</p>`,
  q1: { q: "Kiến trúc tường lửa nào kiểm soát được cả lưu lượng đã mã hóa tới một dịch vụ cụ thể?", o: ["Network-based firewall", "Host-based firewall", "Application firewall", "Không loại nào"], a: 2, e: "Application firewall kiểm soát toàn bộ lưu lượng tới dịch vụ, kể cả lưu lượng đã mã hóa, nhưng luật phức tạp." },
  q2: { q: "Chọn các phát biểu đúng.", o: ["IDPS theo dõi chuỗi gói tin hoặc hành vi, còn tường lửa xử lý từng gói tin", "Phát hiện bất thường xây dựng mô hình hành vi bình thường", "Tường lửa ngăn chặn tốt mọi mối đe dọa từ bên trong", "Cân bằng tải và mở rộng băng thông giúp chống DoS băng thông"], a: [0, 1, 3], e: "Tường lửa không bảo vệ được trước các mối nguy cơ từ bên trong." } }
]}
];
